using System;
using UnityEngine;

namespace PaletteRoom
{
    /// <summary>
    /// Art for the home catalog. Kinds with a prefab use it (scanned models with their zones already set
    /// up); the rest are built in code from the shared materials below. Generated by
    /// Palette Room ▸ Rebuild Furniture Assets.
    /// </summary>
    [CreateAssetMenu(menuName = "Palette Room/Furniture Library", fileName = "FurnitureLibrary")]
    public class FurnitureLibrary : ScriptableObject
    {
        [Serializable]
        public struct PrefabEntry
        {
            public FurnitureKind kind;
            public GameObject prefab;
        }

        [Serializable]
        public struct IconEntry
        {
            public FurnitureKind kind;
            public string variantId;
            public Sprite icon;
        }

        [Tooltip("Prefabs with PaintableZone components on their recolorable parts.")]
        public PrefabEntry[] prefabs = Array.Empty<PrefabEntry>();

        [Tooltip("Small baked pictures of each piece for 2D lists such as the shopping list.")]
        public IconEntry[] icons = Array.Empty<IconEntry>();

        [Header("Materials for code-built pieces")]
        [Tooltip("Linen upholstery; grayscale so the palette tint reads true.")]
        public Material upholstery;
        [Tooltip("Wool bouclé for the rug; grayscale for tinting.")]
        public Material rugWeave;
        [Tooltip("Painted wood / lacquer for table tops and shelving.")]
        public Material paint;
        [Tooltip("Natural white oak for legs and frames (never tinted).")]
        public Material oak;
        [Tooltip("Dark powder-coated metal.")]
        public Material metal;
        [Tooltip("Warm glowing bulb.")]
        public Material bulb;

        public Sprite IconFor(FurnitureKind kind, string variantId)
        {
            foreach (var e in icons)
            {
                if (e.kind == kind && e.variantId == variantId)
                    return e.icon;
            }
            return null;
        }

        public GameObject PrefabFor(FurnitureKind kind)
        {
            foreach (var e in prefabs)
            {
                if (e.kind == kind && e.prefab != null)
                    return e.prefab;
            }
            return null;
        }
    }
}
